public static class BuildNightEvent {
 static RectTransform R(string n,Transform p,float x,float y,float w,float h){var g=new GameObject(n,typeof(RectTransform));g.transform.SetParent(p,false);var r=(RectTransform)g.transform;r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);return r;}
 static Text T(string n,Transform p,float x,float y,float w,float h,Text template,int size){var t=UnityEngine.Object.Instantiate(template,p);t.name=n;var r=t.rectTransform;r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);t.fontSize=size;t.alignment=TextAnchor.UpperLeft;t.lineSpacing=.86f;t.text="";t.raycastTarget=false;t.gameObject.SetActive(true);return t;}
 static Button B(string n,Transform p,float x,float y,float w,float h,SettlementOpeningChapter o,string label){var b=UnityEngine.Object.Instantiate(o.Back,p);b.name=n;b.onClick=new Button.ButtonClickedEvent();var r=(RectTransform)b.transform;r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);var t=b.GetComponentInChildren<Text>();t.rectTransform.anchorMin=Vector2.zero;t.rectTransform.anchorMax=Vector2.one;t.rectTransform.offsetMin=new Vector2(20,4);t.rectTransform.offsetMax=new Vector2(-20,-4);t.fontSize=27;t.alignment=TextAnchor.MiddleLeft;t.text=label;return b;}
 public static string Run(){const string path="Assets/Prefabs/Settlement/SettlementScreen.prefab";var root=PrefabUtility.LoadPrefabContents(path);try{var o=root.GetComponent<SettlementOpeningChapter>();var old=root.transform.Find("SettlementNightEvent");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var view=R("SettlementNightEvent",null,0,0,1920,1080);view.gameObject.AddComponent<PopupBackgroundHud>();var dim=R("Dim",view,0,0,1920,1080).gameObject.AddComponent<Image>();dim.color=new Color(0,0,0,.97f);var heading=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Settlement/PopupHeading.prefab"),view);heading.GetComponentInChildren<Text>().text="정착지 · 밤의 사건";PrefabUtility.RecordPrefabInstancePropertyModifications(heading.GetComponentInChildren<Text>());var paper=R("Paper",view,450,200,1020,700).gameObject.AddComponent<Image>();paper.sprite=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Art/PartySelection/card-paper.png");paper.raycastTarget=false;T("Title",view,494,238,932,60,o.EventTitle,40);T("Body",view,494,324,932,266,o.EventBody,28);T("Result",view,494,590,932,240,o.EventBody,23);var choices=R("Choices",view,494,658,932,160);B("Listen",choices,0,0,932,70,o,"대답 없이 귀 기울이기     · 15분");B("Look",choices,0,88,932,70,o,"불빛을 가리고 살피기     · 30분");var back=B("Back",view,80,974,410,76,o,"나중에 결정하기");back.GetComponentInChildren<Text>().alignment=TextAnchor.MiddleCenter;var asset=PrefabUtility.SaveAsPrefabAsset(view.gameObject,"Assets/Prefabs/Settlement/SettlementNightEvent.prefab");UnityEngine.Object.DestroyImmediate(view.gameObject);var panel=(GameObject)PrefabUtility.InstantiatePrefab(asset,root.transform);o.NightView=panel;o.NightChoices=panel.transform.Find("Choices").gameObject;o.NightTitle=panel.transform.Find("Title").GetComponent<Text>();o.NightBody=panel.transform.Find("Body").GetComponent<Text>();o.NightResult=panel.transform.Find("Result").GetComponent<Text>();o.NightListen=panel.transform.Find("Choices/Listen").GetComponent<Button>();o.NightLook=panel.transform.Find("Choices/Look").GetComponent<Button>();o.NightBack=panel.transform.Find("Back").GetComponent<Button>();o.NightBackLabel=o.NightBack.GetComponentInChildren<Text>();panel.SetActive(false);PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}AssetDatabase.SaveAssets();EditorSceneManager.OpenScene("Assets/Scenes/Settlement.unity");return "Night choice popup built with common heading/dim/footer and paper ink palette.";}
